console.log('flight_bookings schema:', schema.sql);
console.log('---');

// Search for B75309
const rows = db.prepare(\"SELECT * FROM flight_bookings WHERE reservation_id LIKE '%B75309%' OR id LIKE '%B75309%'\").all();
console.log('Rows matching B75309:', JSON.stringify(rows, null, 2));
"

